package com.example

/**
 * Domain 8: Socio-Economic Transformations, Plantation Economy & National-Religious Revival
 * (වැවිලි ආර්ථිකය, යටිතල පහසුකම්, බෞද්ධ/හින්දු/මුස්ලිම් පුනරුදය, අමද්‍යප ව්‍යාපාරය, 1915 කෝලාහල)
 * Clean Sinhala questions aligned with syllabus. NO lesson title prefixes.
 */
object HistoryLiveExamSocioRevivalBank {
  private val T = HistoryTopicDomain.SOCIO_ECONOMIC_REVIVAL

  private fun q(
    topic: HistoryTopicDomain,
    stem: String,
    correct: String,
    distractor1: String,
    distractor2: String,
    distractor3: String,
    explanation: String
  ): HistoryCuratedQuestion {
    return HistoryCuratedQuestion(
      stem = stem,
      options = listOf(correct, distractor1, distractor2, distractor3),
      correctIndex = 0,
      explanation = explanation,
      topic = topic
    )
  }

  fun socioEconomicAndRevivalQuestions(): List<HistoryCuratedQuestion> = listOf(
    q(T, "ශ්‍රී ලංකාවේ ප්‍රථම වරට වාණිජ මට්ටමින් තේ වගාව ආරම්භ කළ බ්‍රිතාන්‍ය පුරෝගාමියා කවුද?", "ජේම්ස් ටේලර් (James Taylor)", "තෝමස් ලිප්ටන්", "එඩ්වඩ් බාන්ස්", "ජෝර්ජ් බර්ඩ්", "1867 දී මහනුවර හේවාහැට ලූල්කඳුර (Loolecondera) වත්තේ අක්කර 19 ක භූමියක ජේම්ස් ටේලර් විසින් තේ වගාව ආරම්භ කරන ලදී."),
    q(T, "ජේම්ස් ටේලර් විසින් ශ්‍රී ලංකාවේ වාණිජ තේ වගාව ආරම්භ කළ ඓතිහාසික වතුයාය කුමක්ද?", "ලූල්කඳුර වත්ත (Loolecondera Estate)", "ඩෙවෝන් වත්ත", "ලැබූකැලේ වත්ත", "නෝවුඩ් වත්ත", "ලූල්කඳුර වත්තේ තම නිවසේ ආලින්දයේදී තේ දළු අතින් අඹරා ප්‍රථම තේ නිපදවීම ජේම්ස් ටේලර් විසින් සිදු කළේය."),
    q(T, "ශ්‍රී ලංකාවේ ප්‍රථම තේ වෙන්දේසිය (Tea Auction) කොළඹදී පවත්වන ලද්දේ කුමන වර්ෂයේදීද?", "ක්‍රි.ව. 1883 දී", "ක්‍රි.ව. 1867 දී", "ක්‍රි.ව. 1890 දී", "ක්‍රි.ව. 1905 දී", "කොළඹ තේ වෙළඳුන්ගේ සංගමය මගින් 1883 දී ආරම්භ කළ කොළඹ තේ වෙන්දේසිය අද ලොව විශාලතම තේ වෙන්දේසි මධ්‍යස්ථානයකි."),
    q(T, "ශ්‍රී ලංකාවට රබර් වගාව මුල්වරට හඳුන්වා දීම සඳහා ඇමසන් වනාන්තරයෙන් රබර් බීජ රැගෙන ආවේ කවුද?", "ශ්‍රීමත් හෙන්රි වික්හැම් (Sir Henry Wickham)", "ජේම්ස් ටේලර්", "තෝමස් ලිප්ටන්", "ජෝර්ජ් වොලන්", "බ්‍රසීලයේ ඇමසන් වනාන්තරයෙන් හොර රහසේ රැගෙන ආ හෙවියා බ්‍රසිලියන්සිස් රබර් බීජ එංගලන්තයේ කිව් උද්‍යානයේදී පැළ කර ලංකාවට එවන ලදී."),
    q(T, "ශ්‍රී ලංකාවේ ප්‍රථම රබර් පැළ රෝපණය කරන ලද්දේ කුමන උද්භිද උද්‍යානයේදීද?", "ගම්පහ හෙනරත්ගොඩ උද්භිද උද්‍යානයේදී (1876)", "පේරාදෙණිය උද්භිද උද්‍යානයේදී", "හක්ගල උද්භිද උද්‍යානයේදී", "මිරිජ්ජවිල උද්භිද උද්‍යානයේදී", "1876 දී හෙනරත්ගොඩ උද්‍යානයේ රෝපණය කළ රබර් පැළවලින් ආසියාව පුරා රබර් වගාව ව්‍යාප්ත විය."),
    q(T, "ශ්‍රී ලංකාවේ රබර් ගස්වලින් කිරි කැපීමේ (Tapping) විද්‍යාත්මක ක්‍රමවේදය සොයාගත් උද්භිද විද්‍යාඥයා කවුද?", "හෙන්රි රිඩ්ලි (Henry Ridley)", "ජේම්ස් ටේලර්", "හෙන්රි වික්හැම්", "විලියම් ග්‍රෙගරි", "ගසට හානි නොවන පරිදි V හැඩයට කැපුම් යොදා රබර් කිරි ලබාගැනීමේ ක්‍රමය හඳුන්වා දීමෙන් රබර් නිෂ්පාදනය ඉහළ ගියේය."),
    q(T, "ශ්‍රී ලංකාවේ 'පොල් ත්‍රිකෝණය' (Coconut Triangle) ලෙස හඳුන්වන ප්‍රදේශය මායිම් වන නගර ත්‍රිත්වය මොනවාද?", "කුරුණෑගල, පුත්තලම සහ කොළඹ", "ගාල්ල, මාතර, හම්බන්තොට", "මහනුවර, මාතලේ, නුවරඑළිය", "යාපනය, මන්නාරම, වවුනියාව", "මෙරට වාණිජ පොල් වගාව බහුලවම සංකේන්ද්‍රණය වී ඇත්තේ මෙම පොල් ත්‍රිකෝණය තුළය."),
    q(T, "යුරෝපීය වැවිලිකරුවන් සතුවූ තේ සහ රබර් වතුවලට වඩා වෙනස්ව, පොල් වගාවේ පැවති සුවිශේෂී ආර්ථික ලක්ෂණය කුමක්ද?", "පොල් වගාවේ වැඩි හිමිකාරිත්වය දේශීය සිංහල ඉඩම් හිමියන් සතුව පැවතීම", "පොල් පිටරට නොයැවීම", "පොල් රජයේ ඒකාධිකාරයක් වීම", "පොල් වැවීමට ජලය අනවශ්‍ය වීම", "දේශීය මධ්‍යම පාන්තික සහ ධනපති පන්තිය ගොඩනැගීමට පොල් වගාව බෙහෙවින් ඉවහල් විය."),
    q(T, "කඳුකරයේ තේ සහ කෝපි වතුවල සේවය සඳහා දකුණු ඉන්දියාවෙන් දෙමළ ශ්‍රමිකයන් බඳවා ගත් දේශීය ක්‍රමය කුමක්ද?", "කන්ගානි ක්‍රමය (Kangany System)", "රාජකාරි ක්‍රමය", "වහල් ක්‍රමය", "කොන්ත්‍රාත් ක්‍රමය", "කන්ගානිවරුන් මගින් ගම්මානවලින් ශ්‍රමිකයන් කණ්ඩායම් වශයෙන් මෙරටට ගෙන ආ අතර 'තුණ්ඩු ක්‍රමය' මගින් ඔවුන් ණය බරිත කර රඳවා ගන්නා ලදී."),
    q(T, "බ්‍රිතාන්‍ය වතුවල සේවය කළ ඉන්දියානු දෙමළ වතු කම්කරුවන්ගේ නවාතැන් හැඳින්වූයේ කුමන නමින්ද?", "ලයින් කාමර (Line Rooms)", "බංගලා", "වාඩි", "කුටි", "අතිශය පටු, සනීපාරක්ෂක පහසුකම් අවම වූ ලයින් කාමර පේළිවල ජීවත්වීමට වතු කම්කරුවන්ට සිදුවිය."),
    q(T, "බ්‍රිතාන්‍ය යුගයේදී වැවිලි භාණ්ඩ කොළඹ වරායට ප්‍රවාහනය කිරීම කාර්යක්ෂම කිරීම සඳහා ඉදිකළ ප්‍රධාන යටිතල පහසුකම කුමක්ද?", "දුම්රිය මාර්ග පද්ධතිය (Railway Network)", "ගුවන් තොටුපළවල්", "ඇළ මාර්ග", "කරත්ත පාරවල්", "කොළඹ සිට මහනුවර, නාවලපිටිය, නානුඔය සහ බණ්ඩාරවෙල දක්වා උඩරට දුම්රිය මාර්ගය ඉදිකරන ලද්දේ තේ සහ කෝපි ප්‍රවාහනයටයි."),
    q(T, "ක්‍රි.ව. 1875 සිට 1885 දක්වා කාලය තුළ කොළඹ වරාය ලෝකයේ ප්‍රමුඛ කෘත්‍රිම වරායක් බවට පත්කළ සංවර්ධනය කුමක්ද?", "නිරිතදිග දියකඩනය (South-West Breakwater) ඉදිකිරීම", "ගාලු වරාය වැසීම", "වරාය පෞද්ගලීකරණය", "නැව් තැනීම", "ශ්‍රීමත් ජෝන් කූඩ්ගේ සැලසුමකට අනුව ඉදිකළ දියකඩනය නිසා ඕනෑම කාලගුණයකදී විශාල වාෂ්ප නැව්වලට කොළඹ වරායට ඇතුළුවීමට හැකි විය."),
    q(T, "19 වන සියවසේ අගභාගයේදී ශ්‍රී ලංකාවේ දේශීය ධනපති පන්තියක් බිහිවීමට බලපෑ ප්‍රධාන ඛනිජ කර්මාන්තය කුමක්ද?", "මිනිරන් කර්මාන්තය (Plumbago / Graphite Mining)", "මැණික් ගැරීම", "රන් සේදීම", "යකඩ උණු කිරීම", "බෝගල, කහටගහ ඇතුළු පතල්වලින් මිනිරන් කැණීම මගින් දොන් චාල්ස් සේනානායක, ජෝන් කොතලාවල වැනි දේශීය පවුල් විශාල ධනස්කන්ධයක් උපයා ගත්හ."),
    q(T, "බ්‍රිතාන්‍ය යුගයේදී මිනිරන්, අරක්කු රේන්ද සහ පොල් වගාවෙන් ධනවත් වූ මෙරට ශ්‍රේෂ්ඨතම දානපතියා කවුද?", "චාල්ස් හෙන්රි ද සොයිසා (C. H. de Soysa)", "ජේම්ස් පීරිස්", "පොන්නම්බලම් රාමනාදන්", "ඩී. ඇස්. සේනානායක", "ද සොයිසා මාතෘ රෝහල, වේල්ස් කුමර හා කුමරි විද්‍යාල ඉදිකරමින් ලංකාවේ මෙන්ම එංගලන්තයේ රෝහල්වලට පවා අතිවිශාල ධන පරිත්‍යාග කළ අසමසම දානපතියා විය."),
    q(T, "19 වන සියවසේදී බ්‍රිතාන්‍ය ක්‍රිස්තියානි මිෂනාරිවරුන් විසින් බුදුදහමට එරෙහිව කළ ප්‍රහාරයන්ට මුහුණ දීමට සිංහල බෞද්ධයන් විසින් පැවැත්වූ විවාද හැඳින්වෙන්නේ කුමන නමින්ද?", "පංච මහා වාද (Five Great Debates)", "ධර්ම සාකච්ඡා", "සංගායනා", "රාජකීය විවාද", "බද්දේගම, වරගොඩ, උදම්විට, ගම්පොළ සහ පානදුර යන ස්ථාන 5 කදී ප්‍රසිද්ධ වාද පැවැත්විණි."),
    q(T, "පංච මහා වාද අතරින් ලෝක ප්‍රසිද්ධියට පත් වූ, බෞද්ධ පුනරුදයේ හැරවුම් ලක්ෂ්‍යය වූ ඓතිහාසික විවාදය කුමක්ද?", "පානදුරාවාදය 1873 (Panadura Debate)", "බද්දේගම වාදය", "ගම්පොළ වාදය", "උදම්විට වාදය", "1873 අගෝස්තු 26 සහ 28 දෙදින පානදුර ගල්කන්ද විහාරයේදී පැවති මෙම විවාදයෙන් බෞද්ධ පාර්ශ්වය අතිවිශිෂ්ට ජයග්‍රහණයක් ලැබීය."),
    q(T, "පානදුරාවාදයේදී බෞද්ධ පාර්ශ්වය වෙනුවෙන් තර්ක කරමින් 'වාදීභසිංහ' නාමය ලැබූ අභීත හිමිපාණන් කවුද?", "පූජ්‍ය මිගෙට්ටුවත්තේ ගුණානන්ද හිමි (Ven. Migettuwatte Gunananda)", "හික්කඩුවේ ශ්‍රී සුමංගල හිමි", "රත්මලානේ ධර්මාලෝක හිමි", "වැලවිට සරණංකර හිමි", "මිගෙට්ටුවත්තේ ගුණානන්ද හිමියන්ගේ අසහාය වාග් චාතුර්‍යය සහ තර්ක ශක්තිය හමුවේ ක්‍රිස්තියානි පාර්ශ්වයේ තර්ක බිඳ වැටිණි."),
    q(T, "පානදුරාවාදයේදී ක්‍රිස්තියානි පාර්ශ්වය වෙනුවෙන් ප්‍රධානත්වයෙන් විවාද කළ පූජකතුමන්ලා කවුරුන්ද?", "දාවිත් ද සිල්වා පියතුමා සහ සිරිමන්ත පෙරේරා", "ජේම්ස් කැස්ටන්", "ක්‍රිස්ටෝෆර් එලියට්", "ජෝන් ඩොයිලි", "වෙස්ලියන් මිෂනාරි දාවිත් ද සිල්වා ගරු පියතුමා ඇතුළු පිරිස ක්‍රිස්තියානි පාර්ශ්වය මෙහෙයවූහ."),
    q(T, "පානදුරාවාදයේ සම්පූර්ණ විස්තරය ඉංග්‍රීසි බසට පරිවර්තනය කර 'ද සිලෝන් ටයිම්ස්' පුවත්පතේ පළ කළ බ්‍රිතාන්‍ය ජාතිකයා කවුද?", "ජෝන් කැපර් (John Capper)", "කර්නල් ඕල්කට්", "ජෝන් ඩොයිලි", "විලියම් ග්‍රෙගරි", "ජෝන් කැපර්ගේ වාර්තාව කියවීමෙන් ඇමරිකාවේ විසූ හෙන්රි ස්ටීල් ඕල්කට්තුමා ලංකාවට පැමිණීමට පෙළඹිණි."),
    q(T, "ක්‍රි.ව. 1873 දී කොළඹ මාළිගාකන්දේ විද්‍යෝදය පිරිවෙන ආරම්භ කළ ශ්‍රේෂ්ඨ යතිවරයාණන් කවුද?", "පූජ්‍ය හික්කඩුවේ ශ්‍රී සුමංගල නාහිමි", "රත්මලානේ ධර්මාලෝක හිමි", "මිගෙට්ටුවත්තේ ගුණානන්ද හිමි", "වාලීසිංහ හරිශ්චන්ද්‍ර", "පෙරදිග භාෂා සහ ධර්ම ශාස්ත්‍රීය පුනරුදයේ කේන්ද්‍රස්ථානයක් ලෙස විද්‍යෝදය පිරිවෙන ගොඩනැගිණි."),
    q(T, "ක්‍රි.ව. 1875 දී පෑලියගොඩ විද්‍යාලංකාර පිරිවෙන ආරම්භ කළ මහා ප්‍රඥාවන්ත හිමිපාණන් කවුද?", "පූජ්‍ය රත්මලානේ ශ්‍රී ධර්මාලෝක නාහිමි", "හික්කඩුවේ සුමංගල හිමි", "මිගෙට්ටුවත්තේ ගුණානන්ද හිමි", "කිරිවත්තුඩුවේ ප්‍රඥාසාර හිමි", "විද්‍යාලංකාර පිරිවෙන මෙරට භික්ෂු අධ්‍යාපනය සහ සාහිත්‍ය පර්යේෂණ උසස් තලයකට ඔසවා තැබීය."),
    q(T, "පානදුරාවාදයේ තොරතුරු කියවා බුදුදහම පිළිබඳ පැහැදී 1880 දී ශ්‍රී ලංකාවට පැමිණි ඇමරිකානු ජාතිකයා කවුද?", "කර්නල් හෙන්රි ස්ටීල් ඕල්කට් (Col. Henry Steel Olcott)", "බ්ලැවට්ස්කි මැතිනිය", "ඇලෙක්සැන්ඩර් බෙල්", "තෝමස් එඩිසන්", "ඕල්කට්තුමා සහ බ්ලැවට්ස්කි මැතිනිය ගාල්ල විජයානන්ද විහාරයේදී පංචසීලය සමාදන් වී බෞද්ධයන් බවට පත්වූහ."),
    q(T, "කර්නල් ඕල්කට්තුමාගේ මූලිකත්වයෙන් බෞද්ධ අධ්‍යාපනය නගාසිටුවීම සඳහා පිහිටුවන ලද සමිතිය කුමක්ද?", "පරමවිඥානාර්ථ බෞද්ධ සංගමය (Buddhist Theosophical Society - BTS)", "මහාබෝධි සංගමය", "තරුණ බෞද්ධ සංගමය", "තාරුණ්‍යයේ බෞද්ධ පෙරමුණ", "1880 දී පිහිටුවූ මෙම සංගමය මගින් ලංකාව පුරා බෞද්ධ පාසල් සිය ගණනක් ආරම්භ කරන ලදී."),
    q(T, "කර්නල් හෙන්රි ස්ටීල් ඕල්කට්තුමාගේ මගපෙන්වීම යටතේ කොළඹදී ආරම්භ කරන ලද ප්‍රමුඛතම බෞද්ධ පිරිමි විද්‍යාලය කුමක්ද?", "ආනන්ද විද්‍යාලය (Ananda College)", "නාලන්දා විද්‍යාලය", "ධර්මරාජ විද්‍යාලය", "මලියදේව විද්‍යාලය", "1886 දී පිටකොටුවේ මැලිබන් වීදියේ බෞද්ධ ඉංග්‍රීසි පාසල ලෙස ඇරඹී පසුව ආනන්ද විද්‍යාලය බවට පත්විය."),
    q(T, "බෞද්ධ දරුවන්ට තම ආගමික පරිසරයක ඉංග්‍රීසි අධ්‍යාපනය දීම සඳහා බිහිවූ ප්‍රධාන පාසල් නොවන්නේ කුමක්ද?", "ශාන්ත තෝමස් විද්‍යාලය සහ ත්‍රිත්ව විද්‍යාලය", "ආනන්ද සහ නාලන්දා විද්‍යාල (කොළඹ)", "ධර්මරාජ විද්‍යාලය (මහනුවර) සහ මලියදේව (කුරුණෑගල)", "මහාමායා (මහනුවර) සහ විශාකා (කොළඹ)", "ශාන්ත තෝමස් සහ ත්‍රිත්ව විද්‍යාල ක්‍රිස්තියානි මිෂනාරි පාසල් වේ; අනෙක්වා බෞද්ධ පාසල්ය."),
    q(T, "ලෝක බෞද්ධ ජනතාවගේ ප්‍රධාන ආගමික සංකේතය වන 'ෂඩ්වර්ණ බෞද්ධ ධජය' (Buddhist Flag) නිර්මාණය කළේ කවුරුන්ද?", "කොළඹ බෞද්ධාරක්ෂක කමිටුව (ඕල්කට්තුමාගේ අනුමැතිය ඇතිව)", "මිගෙට්ටුවත්තේ හිමි", "අනගාරික ධර්මපාල", "බ්‍රිතාන්‍ය ආණ්ඩුකාරවරයා", "බුදුරදුන්ගේ ශරීරයෙන් විහිදුණු ෂඩ්වර්ණ රශ්මි මාලාව පදනම් කරගෙන 1885 දී ප්‍රථම වරට මෙම ධජය නිර්මාණය කර එසවීය."),
    q(T, "බ්‍රිතාන්‍ය යටත්විජිත රජය විසින් වෙසක් පුන් පොහෝ දිනය මෙරට රජයේ නිවාඩු දිනයක් බවට පත්කළේ කුමන වර්ෂයේදීද?", "ක්‍රි.ව. 1885 දී", "ක්‍රි.ව. 1815 දී", "ක්‍රි.ව. 1848 දී", "ක්‍රි.ව. 1948 දී", "කර්නල් ඕල්කට්තුමාගේ දැඩි රාජ්‍යතාන්ත්‍රික මැදිහත්වීම හේතුවෙන් 1885 වෙසක් පොහොය දින රජයේ ප්‍රසිද්ධ නිවාඩු දිනයක් ලෙස ප්‍රකාශයට පත් විය."),
    q(T, "දොන් ඩේවිඩ් හේවාවිතාරණ නමින් උපත ලබා, පසුව බෞද්ධ පුනරුදයේ හා ජාතික නිදහස් අරගලයේ අසහාය නායකයා බවට පත්වූයේ කවුද?", "අනගාරික ධර්මපාලතුමා (Anagarika Dharmapala)", "වාලිසිංහ හරිශ්චන්ද්‍ර", "පියදාස සිරිසේන", "ඩී. බී. ජයතිලක", "තම දිවියම බුදුසසුන සහ නිදහස වෙනුවෙන් කැප කරමින් ගිහිගෙය හැරදමා බ්‍රහ්මචාරී ජීවිතයක් ගත කළ ධර්මපාලතුමා අනගාරික ප්‍රතිපදාව වැළඳගත්තේය."),
    q(T, "ඉන්දියාවේ බුද්ධගයාව ඇතුළු බෞද්ධ සිද්ධස්ථාන බේරාගැනීම සඳහා අනගාරික ධර්මපාලතුමා විසින් 1891 දී පිහිටුවූ සංවිධානය කුමක්ද?", "මහාබෝධි සමාගම (Maha Bodhi Society)", "පරමවිඥානාර්ථ සමාගම", "තරුණ බෞද්ධ සමිතිය", "බෞද්ධ මහා සම්මේලනය", "හින්දු මහන්තාගේ පාලනයට නතුව තිබූ බුද්ධගයාව යළි බෞද්ධයන් සතු කරගැනීමට මහාබෝධි සමාගම මගින් ජාත්‍යන්තර අරගලයක් දියත් කරන ලදී."),
    q(T, "අනගාරික ධර්මපාලතුමා විසින් සිංහල බෞද්ධ ජනතාව දැනුවත් කිරීම සඳහා ආරම්භ කළ පුවත්පත කුමක්ද?", "සිංහල බෞද්ධයා (The Sinhala Bauddhaya)", "දිනමිණ", "ලක්මිණිපහණ", "ඥානාර්ථ ප්‍රදීපය", "1906 දී ආරම්භ කළ සිංහල බෞද්ධයා පුවත්පත මගින් ජාතික, ආගමික හා ආර්ථික නිදහස පිළිබඳ දැඩි මතවාද සමාජගත කෙරිණි."),
    q(T, "'දැනගව් සිංහලයෙනි, පිබිදෙව්! මව්බිම සහ බුදුසසුන රකින්න!' යනුවෙන් මුළු රට පුරා හඬ නැගූ නායකයා කවුද?", "අනගාරික ධර්මපාලතුමා", "කර්නල් ඕල්කට්", "මිගෙට්ටුවත්තේ ගුණානන්ද හිමි", "වාලිසිංහ හරිශ්චන්ද්‍ර", "ධර්මපාලතුමා තම ජීවිත කාලය පුරාම කරත්තයක නැගී ගමින් ගමට යමින් ජනතාව අමතා ජාතිකාභිමානය අවදි කළේය."),
    q(T, "අනගාරික ධර්මපාලතුමා තම ජීවිතයේ අවසාන භාගයේදී පැවිදි දිවියට ඇතුළත් වූයේ කුමන නමින්ද?", "සිරි දේවමිත්ත ධම්මපාල හිමි", "වාදීභසිංහ හිමි", "ඥානානන්ද හිමි", "සුමංගල හිමි", "ඉන්දියාවේ සාරානාත්හිදී පැවිදි වූ උන්වහන්සේ 'මා මියගිය පසු නැවත ලංකාවේ ඉපිද බුදුසසුන රකින්නට ලැබේවා' යි ප්‍රාර්ථනා කළහ."),
    q(T, "අනුරාධපුර පූජනීය නගරය සුරැකීම, එහි තිබූ මස්කඩ හා සුරාසල් ඉවත් කිරීම වෙනුවෙන් දිවි කැපකළ ජාතික විරුවා කවුද?", "බ්‍රහ්මචාරී වාලිසිංහ හරිශ්චන්ද්‍රතුමා", "අනගාරික ධර්මපාල", "පියදාස සිරිසේන", "ජෝන් ද සිල්වා", "අනුරාධපුර නටබුන් බේරාගැනීමටත්, නූතන නගරය පූජා භූමියෙන් ඉවතට ගෙනයාමටත් වාලිසිංහ හරිශ්චන්ද්‍රතුමා විශිෂ්ට සටනක් කළේය."),
    q(T, "19 වන සියවසේ යාපනයේ හින්දු ආගමික හා දෙමළ සාහිත්‍ය පුනරුදයේ පියා ලෙස සැලකෙන ශ්‍රේෂ්ඨ නායකයා කවුද?", "ශ්‍රීමත් ආරුමුග නාවලර් (Arumuka Navalar)", "පොන්නම්බලම් අරුණාචලම්", "පොන්නම්බලම් රාමනාදන්", "සංගිලි රජු", "ක්‍රිස්තියානි මිෂනාරි ව්‍යාපාරයට එරෙහිව හින්දු සෛව ධර්මය ආරක්ෂා කරමින් යාපනයේ පාසල් සහ මුද්‍රණාල පිහිටුවීමට නාවලර්තුමා මූලික විය."),
    q(T, "ආරුමුග නාවලර්තුමා විසින් හින්දු දරුවන්ට ඉංග්‍රීසි හා හින්දු ආගමික අධ්‍යාපනය ලබාදීම සඳහා යාපනයේ ආරම්භ කළ විද්‍යාලය කුමක්ද?", "යාපනය හින්දු විද්‍යාලය (Jaffna Hindu College / Saiva English School)", "යාපනය මධ්‍ය විද්‍යාලය", "ශාන්ත ජෝන් විද්‍යාලය", "හාර්ට්ලි විද්‍යාලය", "හින්දු සම්ප්‍රදායන්ට අනුකූලව නවීන අධ්‍යාපනය ලබාදීමේ ප්‍රමුඛතම ආයතනය බවට මෙය පත්විය."),
    q(T, "19 වන සියවසේ ශ්‍රී ලංකාවේ මුස්ලිම් ප්‍රජාව අතර නූතන අධ්‍යාපන හා සමාජ පුනරුදයක් ඇතිකළ පුරෝගාමී නායකයා කවුද?", "එම්. සී. සිද්ධි ලෙබ්බේ (M. C. Siddi Lebbe)", "අයි. එල්. එම්. අබ්දුල් අසීස්", "ටී. බී. ජයා", "රාසික් ෆරීඩ්", "මහනුවර උපන් නීතිඥයෙකු වූ සිද්ධි ලෙබ්බේ මුස්ලිම් දරුවන්ට අරාබි අධ්‍යාපනයට අමතරව ඉංග්‍රීසි හා විද්‍යා අධ්‍යාපනය ලබාදීමේ වැදගත්කම අවධාරණය කළේය."),
    q(T, "එම්. සී. සිද්ධි ලෙබ්බේතුමා විසින් මුස්ලිම් ජනතාව දැනුවත් කිරීම සඳහා ප්‍රකාශයට පත් කළ ප්‍රථම මුස්ලිම් පුවත්පත කුමක්ද?", "මුස්ලිම් නේසන් (Muslim Nesan)", "ඉස්ලාම් මිත්‍රයා", "දිනමිණ", "ලක්මිණිපහණ", "1882 දී කොළඹින් පළකළ මුස්ලිම් නේසන් පුවත්පත මගින් නූතන අධ්‍යාපනය හා සංස්කෘතික අනන්‍යතාව පිළිබඳව ලිපි පළවිය."),
    q(T, "එම්. සී. සිද්ධි ලෙබ්බේ සහ අරාබි පාෂාගේ මූලිකත්වයෙන් 1892 දී කොළඹ මරදානේ ආරම්භ කළ ප්‍රමුඛ මුස්ලිම් පාසල කුමක්ද?", "කොළඹ සහිරා විද්‍යාලය (Zahira College)", "අල් හිදායා විද්‍යාලය", "මුස්ලිම් කාන්තා විද්‍යාලය", "වෙස්ලි විද්‍යාලය", "ශ්‍රී ලංකාවේ මුස්ලිම් ජාතික අධ්‍යාපනයේ කේන්ද්‍රස්ථානය ලෙස සහිරා විද්‍යාලය බිහිවිය."),
    q(T, "ඊජිප්තුවේ බ්‍රිතාන්‍ය විරෝධී නිදහස් සටනක් මෙහෙයවා මෙරටට පිටුවහල් කර සිටිමින් ලංකාවේ මුස්ලිම් පුනරුදයට දායක වූ ඊජිප්තු ජාතිකයා කවුද?", "අහමඩ් අරාබි පාෂා (Orabi Pasha)", "කමල් අතාවුර්ක්", "සාද් සාග්ලුල්", "මොහොමඩ් අලි", "සිද්ධි ලෙබ්බේ සමග එක්ව මුස්ලිම් ජාතික ඇඳුම (ෆෙස් තොප්පිය) මෙරට ප්‍රචලිත කිරීමට සහ පාසල් ආරම්භ කිරීමට අරාබි පාෂා දායක විය."),
    q(T, "ක්‍රි.ව. 1912 දී බ්‍රිතාන්‍ය රජය විසින් මෙරට ගම්බිම් පුරා රා තැබෑරුම් ඇරඹීමට හඳුන්වා දුන් ආඥා පනත කුමක්ද?", "සුරාබදු ආඥා පනත (Excise Ordinance of 1912)", "මත්ද්‍රව්‍ය පනත", "පොල් බදු පනත", "කෝල්බෲක් පනත", "රජයේ ආදායම වැඩි කරගැනීමට ගම් නියම්ගම්වල මත්පැන් හල් විවෘත කිරීමට ඉඩ දීමෙන් විශාල සමාජ විරෝධයක් මතුවිය."),
    q(T, "සුරාබදු පනතට එරෙහිව මෙරට ජාතික, ආගමික නායකයන් සියලු දෙනා එක්ව ආරම්භ කළ මහා මහජන ව්‍යාපාරය කුමක්ද?", "අමද්‍යප ව්‍යාපාරය (Temperance Movement)", "සර්වෝදය ව්‍යාපාරය", "චාටිස්ට් ව්‍යාපාරය", "කම්කරු ව්‍යාපාරය", "මත්පැන් පානයෙන් ජාතිය මුදාගැනීමේ මෙම ව්‍යාපාරය පසුකාලීනව අධිරාජ්‍ය විරෝධී නිදහස් සටනේ ප්‍රධාන තවාන බවට පත්විය."),
    q(T, "අමද්‍යප ව්‍යාපාරයේ ප්‍රධාන නායකයන් ලෙස ක්‍රියා කළ සේනානායක පවුලේ සහෝදරයන් තිදෙනා කවුරුන්ද?", "ඩී. සී. සේනානායක, එෆ්. ආර්. සේනානායක සහ ඩී. ඇස්. සේනානායක", "ඩඩ්ලි, රොබට් සහ ජෝන්", "ජේම්ස්, රිචඩ් සහ විලියම්", "ආතර්, චාල්ස් සහ හෙන්රි", "සේනානායක සහෝදරයන් තම ධනය හා කාලය වැය කරමින් රට පුරා අමද්‍යප සමිති පිහිටුවූහ."),
    q(T, "ශ්‍රී ලංකාව පුරා කොස් ගස් ලක්ෂයක් වගා කරමින් ආහාර සුරක්ෂිතතාව හා අමද්‍යප ව්‍යාපාරය වෙනුවෙන් පෙනී සිටි නායකයා කවුද?", "ආතර් වී. දියෙස් හෙවත් කොස් මාමා (Arthur V. Dias)", "පියදාස සිරිසේන", "ඩී. බී. ජයතිලක", "වාලිසිංහ හරිශ්චන්ද්‍ර", "පානදුරේ උපන් ආතර් වී. දියෙස්තුමා ජාතික ආහාර ව්‍යාපාරය හා මත්පැන් විරෝධය දැඩිව ප්‍රවර්ධනය කළේය."),
    q(T, "තම නවකතා සහ පුවත්පත් ලිපි මගින් විදේශීය අනුකරණය හෙළා දකිමින් ජාතික චින්තනය අවදි කළ ප්‍රකට ලේඛකයා කවුද?", "පියදාස සිරිසේන (Piyadasa Sirisena)", "මාටින් වික්‍රමසිංහ", "ඩබ්ලිව්. ඒ. සිල්වා", "කුමාරතුංග මුනිදාස", "'ජයතිස්ස සහ රොසලින්' ඇතුළු නවකතා ලියූ පියදාස සිරිසේන සිංහල ජාතිය පුවත්පත මගින් බටහිර ගැතිභාවයට දැඩි ප්‍රහාර එල්ල කළේය."),
    q(T, "ක්‍රි.ව. 1915 දී ශ්‍රී ලංකාවේ ඇතිවූ සිංහල-මුස්ලිම් කෝලාහලය (1915 Riots) ආරම්භ වීමට බලපෑ ආසන්න සිදුවීම කුමක්ද?", "ගම්පොළ සහ මහනුවර මුස්ලිම් පල්ලියක් ඉදිරිපිටින් බෙර වයමින් පෙරහැරක් ගමන් කිරීම සම්බන්ධ ආරවුල", "වෙළඳ ගැටලුවක්", "ඉඩම් ආරවුලක්", "පාසල් ආරවුලක්", "පෙරහැර චාරිත්‍රයට පොලිසිය හා මුස්ලිම් පාර්ශ්වය බාධා කිරීම නිසා ආරම්භ වූ ගැටුම පළමු ලෝක යුද්ධයේ නොසන්සුන්තාව සමග මුළු දිවයින පුරා පැතිර ගියේය."),
    q(T, "1915 කෝලාහල සමයේදී ලංකාවේ ආණ්ඩුකාරවරයා ලෙස කටයුතු කළ පුද්ගලයා කවුද?", "ශ්‍රීමත් රොබට් චාමර්ස් (Sir Robert Chalmers)", "මැකලම්", "මැනිං", "කෝල්බෲක්", "චාමර්ස් ආණ්ඩුකාරවරයා සිංහල බෞද්ධයන් බ්‍රිතාන්‍ය රජය පෙරළීමට ජර්මනිය සමග කුමන්ත්‍රණය කරන බවට ව්‍යාජ සැකයක් ඇතිකර ගත්තේය."),
    q(T, "1915 දී රොබට් චාමර්ස් ආණ්ඩුකාරවරයා විසින් රට පුරා පනවන ලද මර්දනකාරී නීතිය කුමක්ද?", "දින 100 ක යුද නීතිය (Martial Law)", "හදිසි නීතිය", "ඇඳිරි නීතිය", "ත්‍රස්තවාදී පනත", "යුද නීතිය පනවා කිසිදු වරෙන්තුවක් නොමැතිව සිංහල ජාතික නායකයන් දහස් ගණනක් සිරගත කර වෙඩි තබා ඝාතනය කරන ලදී."),
    q(T, "1915 යුද නීතිය යටතේ කිසිදු නඩු විභාගයකින් තොරව අභූත චෝදනා නගා බ්‍රිතාන්‍යයන් විසින් වෙඩි තබා මරා දැමූ තරුණ විරුවා කවුද?", "කපිතාන් හෙන්රි පේද්‍රිස් (Captain Henry Pedris)", "එඩ්මන්ඩ් හේවාවිතාරණ", "ඩී. ඇස්. සේනානායක", "ඩී. බී. ජයතිලක", "කොළඹ නගරාරක්ෂක හමුදාවේ දක්ෂ නිලධාරියෙකු වූ 27 හැවිරිදි හෙන්රි පේද්‍රිස් ජාතිවාදී කුමන්ත්‍රණයකට වරදකරු කර වැලිකඩ සිරගෙදරදී වෙඩි තබා ඝාතනය කරන ලදී."),
    q(T, "1915 කෝලාහල සමයේදී අත්අඩංගුවට ගෙන යාපනය බන්ධනාගාරයේ රඳවා සිටියදී අභිරහස් ලෙස මියගිය අනගාරික ධර්මපාලතුමාගේ සොහොයුරා කවුද?", "එඩ්මන්ඩ් හේවාවිතාරණ", "චාල්ස් හේවාවිතාරණ", "නීල් හේවාවිතාරණ", "දොන් ඩේවිඩ්", "බ්‍රිතාන්‍ය පාලකයන් විසින් අසාධාරණ ලෙස සිරගත කිරීම නිසා අසනීප වී ඔහු මියගියේය."),
    q(T, "1915 දී බ්‍රිතාන්‍ය රජය විසින් අත්අඩංගුවට ගෙන සිරගත කරන ලද ප්‍රමුඛ ජාතික නායකයන් නොවන්නේ කවුද?", "පොන්නම්බලම් රාමනාදන්", "ඩී. ඇස්. සේනානායක සහ එෆ්. ආර්. සේනානායක", "ඩී. බී. ජයතිලක සහ ඊ. ඩබ්ලිව්. පෙරේරා", "ආචාර්ය සී. ඒ. හේවාවිතාරණ සහ පියදාස සිරිසේන", "පොන්නම්බලම් රාමනාදන් සිරගත නොවූ අතර ඔහු සිරගතව සිටි සිංහල නායකයන් බේරාගැනීමට විශිෂ්ට සටනක් කළේය."),
    q(T, "බ්‍රිතාන්‍ය පාලකයන්ගේ ම්ලේච්ඡ ක්‍රියා පිළිබඳ කරුණු ඇතුළත් රහස් ලියවිල්ල තම සපත්තු අඩියේ සඟවාගෙන ලන්ඩනයට ගිය නායකයා කවුද?", "ඊ. ඩබ්ලිව්. පෙරේරා (E. W. Perera)", "ශ්‍රීමත් ජේම්ස් පීරිස්", "පොන්නම්බලම් රාමනාදන්", "ඩී. ඇස්. සේනානායක", "පළමු ලෝක යුද්ධය පැවති අවදානම් අවස්ථාවේ 'වෙඩි නොවදින පෙරේරා' නමින් ප්‍රකට ඊ. ඩබ්ලිව්. පෙරේරා බ්‍රිතාන්‍ය පාර්ලිමේන්තුවට ගොස් සාක්ෂි ඉදිරිපත් කළේය."),
    q(T, "1915 සිංහල බෞද්ධ නායකයන් බේරාගැනීම සඳහා ව්‍යවස්ථාදායක සභාවේදී සහ බ්‍රිතාන්‍යයට ගොස් නිර්භීතව සටන් කළ ශ්‍රේෂ්ඨ දෙමළ නායකයා කවුද?", "ශ්‍රීමත් පොන්නම්බලම් රාමනාදන් (Sir Ponnambalam Ramanathan)", "පොන්නම්බලම් අරුණාචලම්", "ආරුමුග නාවලර්", "ජී. ජී. පොන්නම්බලම්", "රාමනාදන්තුමාගේ ඓතිහාසික මැදිහත්වීම නිසා බ්‍රිතාන්‍ය රජය යුද නීතිය ඉවත් කර සිරකරුවන් නිදහස් කළ අතර ආණ්ඩුකාර චාමර්ස් ආපසු කැඳවීය."),
    q(T, "ලන්ඩනයේ සිට සිරකරුවන් නිදහස් කරවාගෙන නැවත පැමිණි පොන්නම්බලම් රාමනාදන්තුමාව ජනතාව විසින් පිළිගත්තේ කෙසේද?", "ඔහුගේ අශ්ව කරත්තයෙන් අශ්වයන් ඉවත් කර සිංහල තරුණයන් විසින් තම කරමතින් කරත්තය ඇදගෙන යාමෙන්", "මල් මාලා දමා පමණක්", "රතිඤ්ඤා පත්තු කර", "හමුදා උත්තමාචාර දී", "ජාති භේදයකින් තොරව සිංහල ජනතාව කළගුණ සැලකීමක් ලෙස රාමනාදන්තුමා කොළඹ වරායේ සිට නිවස දක්වා තම කරමතින් රැගෙන ගියහ."),
    q(T, "1915 සිදුවීම්වලින් පසු ආණ්ඩුකාර රොබට් චාමර්ස් සහ හමුදාපති මැල්කම් ධුරවලින් ඉවත් කර ලංකාවට පත්කර එවන ලද නව ආණ්ඩුකාරවරයා කවුද?", "ශ්‍රීමත් ජෝන් ඇන්ඩර්සන් (Sir John Anderson)", "මැනිං", "මැකලම්", "කෝල්බෲක්", "ඇන්ඩර්සන් ආණ්ඩුකාරවරයා පැමිණ පෙර පැවති හමුදා පාලනයේ කෲරත්වය පිළිගෙන පීඩාවට පත් ජනතාවට වන්දි ලබාදීමට පියවර ගත්තේය."),
    q(T, "1915 කෝලාහලයේ ප්‍රතිඵලයක් ලෙස මෙරට දේශපාලනයේ සිදුවූ ප්‍රධානතම පිබිදීම කුමක්ද?", "බ්‍රිතාන්‍ය පාලනයෙන් රට මුදාගැනීම සඳහා ජාතික මට්ටමේ දේශපාලන සංවිධානයක සහ ආණ්ඩුක්‍රම ප්‍රතිසංස්කරණවල අවශ්‍යතාව තදින් දැනීම", "ජාතීන් අතර යුද්ධයක් ඇතිවීම", "ආගමික කටයුතු නතර වීම", "පාසල් වැසී යාම", "සිංහල, දෙමළ, මුස්ලිම් සියලු ප්‍රභූ නායකයන් එක්ව නිදහස් ව්‍යාපාරය දේශපාලන අරගලයක් දක්වා පරිවර්තනය කිරීමට මෙය පදනම දැමීය."),
    q(T, "ක්‍රි.ව. 1862 දී පංච මහා වාදවල ප්‍රථම වාදය පැවැත්වුණේ කුමන ස්ථානයේදීද?", "බද්දේගමදී (බද්දේගම වාදය)", "වරගොඩ", "උදම්විට", "ගම්පොළ", "ක්‍රිස්තියානි මිෂනාරිවරුන් සමග ලිඛිතව හා වාචිකව අදහස් හුවමාරු කරගනිමින් බද්දේගමදී ප්‍රථම විවාදය පැවැත්විණි."),
    q(T, "ක්‍රි.ව. 1865 දී දෙවන ප්‍රසිද්ධ බෞද්ධ-ක්‍රිස්තියානි වාදය පැවැත්වූයේ කුමන ප්‍රදේශයේදීද?", "කැලණියේ වරගොඩදී (වරගොඩ වාදය)", "පානදුරේ", "බද්දේගම", "උදම්විට", "වරගොඩදී පැවති මෙම විවාදයේදී මිගෙට්ටුවත්තේ ගුණානන්ද හිමියෝ බෞද්ධ පාර්ශ්වය ප්‍රබලව මෙහෙයවූහ."),
    q(T, "ක්‍රි.ව. 1866 දී සත්කෝරළයේ පැවැත්වුණු තෙවන ඓතිහාසික විවාදය කුමක්ද?", "උදම්විට වාදය", "වරගොඩ වාදය", "බද්දේගම වාදය", "පානදුරා වාදය", "උදම්විටදී පැවති විවාදයේදී ක්‍රිස්තියානි මත ඛණ්ඩනය කරමින් බෞද්ධ දර්ශනයේ ප්‍රභාශ්වරත්වය තහවුරු කෙරිණි."),
    q(T, "ක්‍රි.ව. 1871 දී මධ්‍යම පළාතේ පැවැත්වුණු සිව්වන මහා විවාදය කුමක්ද?", "ගම්පොළ වාදය", "පානදුරාවාදය", "බද්දේගම වාදය", "වරගොඩ වාදය", "ගම්පොළදී පැවති මෙම වාදයේදීද මිගෙට්ටුවත්තේ ගුණානන්ද හිමියන් ප්‍රමුඛ බෞද්ධ විද්වතුන් ජයග්‍රහණය වාර්තා කළහ."),
    q(T, "බෞද්ධ පුනරුද සමයේ බෞද්ධ පොත්පත් මුද්‍රණය කිරීම සඳහා කොළඹ කොටහේනේ පිහිටුවන ලද මුද්‍රණාලය කුමක්ද?", "සර්වඥ ශාසනෝදය මුද්‍රණාලය", "රජයේ මුද්‍රණාලය", "ලංකා මුද්‍රණාලය", "විද්‍යෝදය මුද්‍රණාලය", "මිගෙට්ටුවත්තේ ගුණානන්ද හිමියන්ගේ නායකත්වයෙන් බෞද්ධ ග්‍රන්ථ හා පත්‍රිකා දහස් ගණනින් මුද්‍රණය කර බෙදාහැරීමට මෙම මුද්‍රණාලය පිහිටුවන ලදී."),
    q(T, "බුදුදහම පිළිබඳ ඇමරිකාවේ හා යුරෝපයේ විද්වතුන් දැනුවත් කිරීම සඳහා ඉංග්‍රීසි භාෂාවෙන් ත්‍රිපිටක ග්‍රන්ථ පරිවර්තනය කළ ආයතනය කුමක්ද?", "පාලි ග්‍රන්ථ සමාගම (Pali Text Society - PTS)", "මහාබෝධි සංගමය", "රාජකීය ආසියාතික සමිතිය", "ලන්ඩන් බෞද්ධ විහාරය", "ටී. ඩබ්ලිව්. රීස් ඩේවිඩ්ස් (T. W. Rhys Davids) මහතා විසින් 1881 දී ලන්ඩනයේදී මෙම සංගමය පිහිටුවන ලදී."),
    q(T, "පාලි ග්‍රන්ථ සමාගමේ ආරම්භකයා වූ රීස් ඩේවිඩ්ස් මහතාට සිංහල සහ පාලි භාෂාව ඉගැන්වූ බෞද්ධ හිමිපාණන් කවුද?", "පූජ්‍ය යට්‍රමුල්ලේ ධම්මාරාම හිමි සහ හික්කඩුවේ ශ්‍රී සුමංගල හිමි", "මිගෙට්ටුවත්තේ ගුණානන්ද හිමි", "රත්මලානේ ධර්මාලෝක හිමි", "වාලීසිංහ හරිශ්චන්ද්‍ර", "බ්‍රිතාන්‍ය සිවිල් නිලධාරියෙකු ලෙස ලංකාවට පැමිණි රීස් ඩේවිඩ්ස් යතිවරයන්ගේ ඇසුරින් පාලි බුදුදහම ගැඹුරින් උගත්තේය."),
    q(T, "විද්‍යෝදය පිරිවෙනේ නිර්මාතෘ හික්කඩුවේ ශ්‍රී සුමංගල නාහිමියන් විසින් ඉටු කරන ලද විශිෂ්ටතම සාහිත්‍ය සේවයක් කුමක්ද?", "මහාවංශය සිංහලට පරිවර්තනය කිරීම සහ බාලාවතාරය ටීකාව ලිවීම", "ජාතක පොත ලිවීම", "පූජාවලිය ලිවීම", "රාජාවලිය ලිවීම", "බටුවන්තුඩාවේ දේවරක්ෂිත පඬිතුමා සමග එක්ව මහාවංශය සංස්කරණය කර සිංහලට පෙරළීමට සුමංගල නාහිමියෝ කටයුතු කළහ."),
    q(T, "විද්‍යාලංකාර පිරිවෙනේ ප්‍රථම පරිවේණාධිපති පූජ්‍ය රත්මලානේ ධර්මාලෝක හිමියන්ගේ ප්‍රධාන ශිෂ්‍යයා වූ සුප්‍රකට පඬිවරයා කවුද?", "පූජ්‍ය රත්මලානේ ශ්‍රී ධර්මාරාම නාහිමි", "කිරිවත්තුඩුවේ ප්‍රඥාසාර හිමි", "බඹරැන්දේ සිරි සීවලී හිමි", "යගිරල පඤ්ඤානන්ද හිමි", "ධර්මාරාම නාහිමියෝ කාව්‍යශේඛරය, පසන් නිබන්ධය සහ ජානකීහරණය වැනි ශ්‍රේෂ්ඨ සාහිත්‍ය කෘති සංස්කරණය කළහ."),
    q(T, "ගාල්ලේ මහින්ද විද්‍යාලය බෞද්ධ දරුවන් වෙනුවෙන් ගොඩනැගීමට තම මුළු ජීවිතයම කැපකළ සුදු ජාතික විදුහල්පතිවරයා කවුද?", "එෆ්. එල්. වුඩ්වර්ඩ් (F. L. Woodward)", "සී. ඩබ්ලිව්. ලෙඩ්බීටර්", "ඒ. ඊ. බුල්ජන්ස්", "පී. ද එස්. කුලරත්න", "කේම්බ්‍රිජ් උපාධිධාරියෙකු වූ වුඩ්වර්ඩ් මහතා මහින්ද විද්‍යාලය උසස් තලයකට ඔසවා තබා බෞද්ධ ග්‍රන්ථ රැසක් ඉංග්‍රීසියට පරිවර්තනය කළේය."),
    q(T, "ආනන්ද විද්‍යාලයේ ප්‍රථම විදුහල්පතිවරයා ලෙස සේවය කළ ඉංග්‍රීසි ජාතික බෞද්ධ විද්වතා කවුද?", "සී. ඩබ්ලිව්. ලෙඩ්බීටර් (C. W. Leadbeater)", "වුඩ්වර්ඩ්", "ඕල්කට්", "බුල්ජන්ස්", "ලෙඩ්බීටර් මහතා බෞද්ධ ඉංග්‍රීසි පාසල සංවිධානය කරමින් බෞද්ධ ළමා සඟරා ප්‍රකාශයට පත් කළේය."),
    q(T, "ආනන්ද විද්‍යාලයේ ප්‍රථම ලාංකික බෞද්ධ විදුහල්පතිවරයා ලෙස පත්වී ආනන්දය ජාතික තලයේ අග්‍රගන්‍ය පාසලක් බවට පත්කළේ කවුද?", "ඒ. ඊ. බුල්ජන්ස් (A. E. Buultjens)", "පී. ද එස්. කුලරත්න", "එල්. එච්. මෙත්තානන්ද", "ඩී. බී. ජයතිලක", "ක්‍රිස්තියානි ආගම අත්හැර බුදුදහම වැළඳගත් බර්ගර් ජාතික කේම්බ්‍රිජ් උපාධිධාරී බුල්ජන්ස් මහතා ආනන්ද විද්‍යාලයේ විශිෂ්ට යුගයක් ආරම්භ කළේය."),
    q(T, "ආනන්ද විද්‍යාලයේ ස්වර්ණමය යුගය නිර්මාණය කරමින් නාලන්දා විද්‍යාලයද බිහිකළ ශ්‍රේෂ්ඨ ලාංකික අධ්‍යාපනඥයා කවුද?", "පී. ද එස්. කුලරත්න (P. de S. Kularatne)", "එල්. එච්. මෙත්තානන්ද", "ඩී. බී. ජයතිලක", "ඊ. ඩබ්ලිව්. පෙරේරා", "කුලරත්න මහතා ආනන්දයේ ශිෂ්‍ය සංඛ්‍යාව දහස් ගණනක් දක්වා වර්ධනය කර නාලන්දා විද්‍යාලයද පිහිටුවීය."),
    q(T, "බෞද්ධ ගැහැනු ළමයින්ගේ උසස් අධ්‍යාපනය වෙනුවෙන් කොළඹ විශාකා විද්‍යාලය ආරම්භ කළ ශ්‍රේෂ්ඨ දානපතිනිය කවුද?", "ජෙරමියස් දියෙස් මැතිනිය (Mrs. Jeremias Dias / සෙලෙස්තිනා රොද්‍රිගෝ)", "මේරි මියුසියස් හිගින්ස්", "හේලේනා විජේවර්ධන", "ලේඩි ස්ටබ්ස්", "පානදුරේ උපන් ජෙරමියස් දියෙස් මැතිනිය තම පෞද්ගලික ධනය වැය කරමින් 'බෞද්ධ බාලිකා විද්‍යාලය' නමින් විශාකා විද්‍යාලය 1917 දී ආරම්භ කළාය."),
    q(T, "ජර්මනියේ උපත ලබා ලංකාවට පැමිණ කොළඹ මියුසියස් බාලිකා විද්‍යාලය ආරම්භ කළ අධ්‍යාපන පුරෝගාමිනිය කවුද?", "මේරි මියුසියස් හිගින්ස් (Marie Musaeus Higgins)", "බ්ලැවට්ස්කි මැතිනිය", "ඇනී බෙසන්ට්", "ජෙරමියස් දියෙස්", "බෞද්ධ ගැහැනු ළමයින්ට නේවාසිකාගාර පහසුකම් සහිතව බෞද්ධ පරිසරයක ඉංග්‍රීසි අධ්‍යාපනය ලබාදීමට ඇය තම මුළු ජීවිතයම කැප කළාය."),
    q(T, "අනගාරික ධර්මපාලතුමාගේ ලෝක බෞද්ධ පුනරුද ව්‍යාපාරයට මූල්‍යමය වශයෙන් දැවැන්ත අනුග්‍රහයක් දැක්වූ ඇමරිකානු දානපතිනිය කවුද?", "මේරි එලිසබෙත් ෆොස්ටර් මැතිනිය (Mary E. Foster)", "බ්ලැවට්ස්කි මැතිනිය", "මියුසියස් හිගින්ස්", "වික්ටෝරියා රැජින", "හවායි දූපත්වල විසූ ෆොස්ටර් මැතිනිය පරිත්‍යාග කළ අතිවිශාල ධනයෙන් ඉන්දියාවේ සහ ලංකාවේ රෝහල්, පාසල් හා බෞද්ධ විහාර රැසක් ඉදිකරන ලදී."),
    q(T, "ක්‍රි.ව. 1926 දී බටහිර ලෝකයේ ප්‍රථම ථේරවාද බෞද්ධ විහාරය ලෙස ලන්ඩන් බෞද්ධ විහාරය (London Buddhist Vihara) පිහිටුවූයේ කවුද?", "අනගාරික ධර්මපාලතුමා", "කර්නල් ඕල්කට්", "හික්කඩුවේ සුමංගල හිමි", "නාරද හිමි", "යුරෝපයේ බුදුදහම ප්‍රචාරය කිරීම සඳහා ධර්මපාලතුමා විසින් එංගලන්තයේ ලන්ඩන් නුවර මෙම ඓතිහාසික විහාරය පිහිටුවීය."),
    q(T, "අනගාරික ධර්මපාලතුමා විසින් දේශීය ආර්ථිකය හා කර්මාන්ත නගාසිටුවීම සඳහා ජනතාවට දුන් උපදෙස කුමක්ද?", "පිටරටින් එන භාණ්ඩ වර්ජනය කර දේශීය කර්මාන්ත හා අත්කම් ආරම්භ කිරීම (ස්වදේශී ව්‍යාපාරය)", "විදේශ ආධාර මත යැපීම", "කර්මාන්තශාලා වැසීම", "ඉංග්‍රීසි භාණ්ඩ පමණක් ගැනීම", "කපු වගාව, රෙදි විවීම, ගිනිකූරු කර්මාන්තය වැනි ස්වදේශික ව්‍යාපාර ආරම්භ කිරීමට එතුමා තරුණයන් ජපානයට යවා පුහුණු කළේය."),
    q(T, "වාලිසිංහ හරිශ්චන්ද්‍රතුමා විසින් අනුරාධපුර පුරාවිද්‍යා නටබුන් බේරාගැනීම සඳහා ලියන ලද ප්‍රකට ග්‍රන්ථය කුමක්ද?", "පුරාවිදු විසිතුර (The Sacred City of Anuradhapura)", "මහාවංශය", "චූලවංශය", "රාජාවලිය", "අනුරාධපුර පූජා භූමියේ පරිශුද්ධත්වය විදේශිකයන්ට සහ ලාංකිකයන්ට පහදා දීමට මෙම කෘතිය සමත් විය."),
